CREATE TABLE IF NOT EXISTS inbound_document_sources(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,source_type TEXT NOT NULL,source_address TEXT,document_family TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'ACTIVE',last_received_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS inbound_document_receipts(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,source_id TEXT,original_filename TEXT NOT NULL,mime_type TEXT NOT NULL,object_key TEXT NOT NULL,sha256 TEXT NOT NULL,received_at TEXT NOT NULL,processing_status TEXT NOT NULL DEFAULT 'QUEUED',duplicate_of TEXT,error_message TEXT,FOREIGN KEY(source_id) REFERENCES inbound_document_sources(id));
CREATE TABLE IF NOT EXISTS inbound_document_extractions(id TEXT PRIMARY KEY,receipt_id TEXT NOT NULL,schema_code TEXT NOT NULL,schema_version TEXT NOT NULL,extracted_json TEXT NOT NULL,confidence REAL NOT NULL DEFAULT 0,validation_status TEXT NOT NULL DEFAULT 'PENDING',validated_by TEXT,validated_at TEXT,FOREIGN KEY(receipt_id) REFERENCES inbound_document_receipts(id));
CREATE TABLE IF NOT EXISTS inbound_document_actions(id TEXT PRIMARY KEY,receipt_id TEXT NOT NULL,action_type TEXT NOT NULL,target_module TEXT NOT NULL,idempotency_key TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'DRAFT',evidence_json TEXT NOT NULL DEFAULT '{}',approved_by TEXT,executed_at TEXT,FOREIGN KEY(receipt_id) REFERENCES inbound_document_receipts(id));
CREATE INDEX IF NOT EXISTS idx_inbound_receipt_scope ON inbound_document_receipts(organization_id,property_id,processing_status,received_at);
